from __future__ import annotations

import uuid
from typing import Any

NS = uuid.UUID("7d3b0c1e-6a8e-4c79-9d7a-2f9a3b6d0e11")


def cid(key: str) -> str:
    return str(uuid.uuid5(NS, key))


def card(name: str, *, set_code: str = "tst", number: str = "1", **extra: Any) -> dict[str, Any]:
    key = f"{name}|{set_code}|{number}"
    base: dict[str, Any] = {
        "object": "card",
        "id": cid(key),
        "oracle_id": cid("oracle|" + name),
        "name": name,
        "lang": "en",
        "layout": "normal",
        "set": set_code,
        "set_name": set_code.upper() + " Set",
        "set_type": "expansion",
        "collector_number": number,
        "released_at": "2020-01-01",
        "rarity": "common",
        "mana_cost": "",
        "cmc": 0.0,
        "type_line": "Artifact",
        "oracle_text": "",
        "colors": [],
        "color_identity": [],
        "keywords": [],
        "legalities": {"commander": "legal"},
        "digital": False,
        "promo": False,
        "border_color": "black",
        "image_uris": {"normal": f"https://img.example/{key}.jpg", "small": f"https://img.example/s/{key}.jpg"},
    }
    base.update(extra)
    return base


